/// <summary>
/// MPJ_28152_CSD_Fulfilment 3.6.2.1 Calculate Qty not reserved
/// </summary>
[DataContractAttribute]
class METQtyNotReservedCalculateContract
{
    RecordSortedList selectedSalesLine;

}

Method.Source:
    /// <summary>
    /// Method to get/set the selected sales line in the contract
    /// </summary>
    /// <param name = "_selectedSalesLine"><c>RecordSortedList</c> of selected sales order lines</param>
    /// <returns><c>RecordSortedList</c> of selected sales order lines</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false), AifCollectionTypeAttribute('_selectedSalesLine', Types::Class, classStr(RecordSortedList))]
    public RecordSortedList parmSelectedSalesLine(RecordSortedList _selectedSalesLine = selectedSalesLine)
    {
        selectedSalesLine = _selectedSalesLine;

        return selectedSalesLine;
    }
